import type { Lesson, Question } from './types';
const topics = [{"track": "os", "slug": "mutex", "title": "Mutex ownership", "idea": "A mutex makes a critical section exclusive and transfers ownership, not just a numeric permit. Lock acquisition must establish acquire ordering; unlocking publishes earlier writes with release ordering.", "problem": "Two threads both pass a balance check before either updates the balance. Serializing only the write still leaves the check outside the invariant.", "steps": ["Acquire the mutex before reading protected state", "Check and update the invariant while holding ownership", "Unlock on every exit path, including errors"], "trade": "A coarse lock simplifies invariants but serializes unrelated operations; fine locks increase concurrency and lock-order risk.", "example": "Balance 100, two debits of 80: one commits, the second sees 20 and rejects. Never check before locking.", "fq": "Why does a mutex differ from a binary semaphore?", "fa": "Mutex ownership supports owner-only unlock and priority inheritance; a semaphore tracks permits and can be posted by another thread."}, {"track": "os", "slug": "semaphore", "title": "Counting semaphores", "idea": "A semaphore represents available units. wait atomically consumes a positive permit or sleeps; post adds a permit and may wake a waiter. It does not itself define which data structure is protected.", "problem": "A producer writes into a full queue because it checks capacity without atomically reserving a slot.", "steps": ["Wait on empty before entering the queue lock", "Insert an item and release the queue lock", "Post full after the item becomes visible"], "trade": "Counting permits models capacity cleanly, but mismatched posts leak capacity or permit overflow.", "example": "Capacity 4, full 3, empty 1: one producer changes counts to full 4, empty 0. Another producer must wait.", "fq": "Can the producer wait on empty while holding the queue mutex?", "fa": "No: a consumer may need that mutex to free a slot. The wait can create a circular dependency."}, {"track": "os", "slug": "spinlock", "title": "Spinlocks and busy waiting", "idea": "A spinlock repeatedly tests an atomic lock word instead of sleeping. It is useful only when the owner will run soon and the protected section is extremely short. Atomic acquisition and memory ordering are separate obligations.", "problem": "On one CPU a high-priority spinner prevents the lower-priority owner from running, so the lock never becomes available.", "steps": ["Atomically attempt an unlocked-to-locked transition", "Use a pause/backoff loop after failure", "Release with the ordering required by the protected data"], "trade": "Spinning avoids sleep/wakeup overhead but burns CPU and increases coherence traffic; sleeping is preferable for long waits.", "example": "A 200 ns critical section may justify spinning on separate cores; a 5 ms disk wait almost never does.", "fq": "Why must kernel spinlock users consider interrupts?", "fa": "An interrupt handler taking a lock held by interrupted code can deadlock on that CPU; the relevant interrupt/preemption rules must be enforced."}, {"track": "os", "slug": "condition-variables", "title": "Monitors and condition variables", "idea": "A monitor combines shared state, a mutex, and condition queues. A condition notification means the predicate may have changed, not that ownership or a resource was transferred. Recheck the predicate in a while loop.", "problem": "Two consumers wake for one item. The first consumes it; the second trusts the notification and reads an empty queue.", "steps": ["Lock the mutex and test the predicate", "Wait atomically releases the mutex and reacquires it before returning", "Recheck the predicate and act while still holding the mutex"], "trade": "notify_one reduces wakeups; notify_all is safer when heterogeneous predicates share a condition but can cause a thundering herd.", "example": "while queue.empty(): wait(cv, mutex); then pop. Spurious wakeups and competing consumers both make if incorrect.", "fq": "Why is unlock followed by sleep not equivalent to condition wait?", "fa": "A producer could signal between the unlock and sleep, losing the notification. Atomic release-and-wait closes that window."}, {"track": "os", "slug": "readers-writers", "title": "Readers–writers synchronization", "idea": "Readers can coexist if no writer mutates the shared object. A writer requires exclusive ownership. Correctness needs an admission policy as well as a reader count; otherwise continuous arrivals can starve a participant.", "problem": "A constant stream of readers keeps a writer waiting forever, even though each individual read is short.", "steps": ["Track active readers under a synchronization primitive", "Block new readers when the selected policy gives a writer priority", "Admit a writer only after active readers drain"], "trade": "Reader preference improves read throughput but can starve writers; writer preference increases reader latency; fair queues cost coordination.", "example": "Five readers may overlap; a waiting writer needs the reader count to reach zero before changing the object.", "fq": "Why might an RW lock be slower than a mutex?", "fa": "Reader bookkeeping can contend on a shared cache line; short critical sections may not amortize that cost."}, {"track": "os", "slug": "dining-philosophers", "title": "Dining philosophers", "idea": "Each participant needs two resources. Local correctness of taking one fork does not imply global progress. Prevent a cycle by imposing a common resource order or limiting admission.", "problem": "Five philosophers each take their left fork and wait for their right fork, making a circular wait.", "steps": ["Assign a total order to forks", "Acquire the lower-numbered required fork first", "Release both after eating and avoid holding a fork while retrying indefinitely"], "trade": "Ordering prevents deadlock but not starvation; an arbitrator can enforce fairness at a coordination cost.", "example": "Number forks 0–4. Every participant takes min(left,right) then max(left,right), so a strictly increasing cycle is impossible.", "fq": "Does allowing only four philosophers to compete solve everything?", "fa": "It breaks the all-five circular hold pattern, but fairness still requires a policy; it is not a starvation proof."}, {"track": "os", "slug": "bankers", "title": "Banker’s algorithm", "idea": "A safe state has at least one order in which all processes can finish using currently available resources plus released allocations. Need equals Max minus Allocation. Unsafe means no guaranteed completion sequence, not necessarily a present deadlock.", "problem": "Granting a seemingly small request consumes the last units that would have allowed any process to finish.", "steps": ["Compute each remaining Need", "Find a process whose Need is componentwise at most Work", "Add its Allocation to Work and repeat until all finish or no process qualifies"], "trade": "Avoidance offers a completion guarantee but requires advance maximum claims and stable resource counts.", "example": "One resource: Available 2; P0 allocated 1/max 3, P1 allocated 2/max 3. Finish P1 first (need 1), Work becomes 4; then P0.", "fq": "Why is an unsafe state not the same as a deadlock?", "fa": "Actual future requests may be smaller than declared maxima. Unsafe means the system cannot guarantee success for every allowed claim."}, {"track": "os", "slug": "priority-inversion", "title": "Priority inversion", "idea": "A high-priority task may depend on a lock held by a low-priority task. Medium-priority runnable work then delays the owner, indirectly delaying high priority. Priority inheritance temporarily boosts the owner.", "problem": "H waits for L's mutex; M repeatedly preempts L. H cannot proceed despite having the highest priority.", "steps": ["Identify the lock owner causing H to block", "Raise the owner's effective priority to the highest blocked waiter", "Restore priority when the dependency ends"], "trade": "Inheritance reduces unbounded inversion but adds bookkeeping and must propagate through nested lock chains.", "example": "L runs at 1, M at 5, H at 10. While H waits on L, inheritance runs L at 10 until it unlocks.", "fq": "Does priority inheritance eliminate deadlocks?", "fa": "No. It changes scheduling priority; it does not remove circular lock dependencies."}, {"track": "os", "slug": "page-tables", "title": "Page tables and translation", "idea": "A virtual address splits into virtual page number and offset. A present page-table entry maps the VPN to a physical frame and records permissions. Translation preserves the page offset; the MMU checks access rights.", "problem": "A valid address is readable but not writable; treating every fault as missing RAM hides a protection violation.", "steps": ["Split the virtual address by page size", "Read the VPN's entry and validate presence and access permissions", "Combine the frame number with the unchanged offset"], "trade": "Small pages reduce internal fragmentation but grow page tables and reduce TLB reach.", "example": "4 KiB pages: VA 0x1234 has VPN 1 and offset 0x234. If VPN 1 maps to PFN 7, PA is 0x7234.", "fq": "Why is translation separate from allocation?", "fa": "An address can be reserved but not resident; the OS decides whether a fault should allocate, load, copy, or reject."}, {"track": "os", "slug": "multi-level-page-tables", "title": "Multi-level page tables", "idea": "A hierarchy allocates lower-level tables only for populated address regions. Upper indices choose table pages, the last index chooses a leaf PTE, and the offset selects a byte. Sparse address spaces avoid flat-table waste.", "problem": "A 32-bit process with only a few mapped pages would still need a full flat table if every VPN had a permanently allocated entry.", "steps": ["Split VPN into level indices", "Follow present upper-level entries to the leaf", "Validate the leaf and form the physical address"], "trade": "Sparse storage saves memory but a cold walk touches multiple table entries; hardware walk caches and huge-page leaves mitigate it.", "example": "32-bit VA, 4 KiB pages, 4-byte PTE: flat table is 2^20 × 4 = 4 MiB. A 10/10/12 split allocates leaf tables on demand.", "fq": "Can a huge page end the walk early?", "fa": "Yes, if an upper-level entry is a permitted large-page leaf; address alignment and architecture rules still apply."}, {"track": "os", "slug": "tlb-asid-pcid", "title": "TLB, ASID and PCID", "idea": "The TLB caches translations including permissions and address-space tags. A miss triggers a page walk; it does not imply a page fault. Tags permit multiple address spaces to coexist without unconditional flushing.", "problem": "An OS remaps a page but leaves an old translation cached on another CPU, so that CPU accesses stale physical memory.", "steps": ["Lookup VPN with the current address-space identity", "Walk page tables after a miss and cache a permitted mapping", "Invalidate matching entries on remapping, including remote CPUs when necessary"], "trade": "Larger TLB reach improves speed; tags and huge pages reduce misses but require correct lifetime and invalidation management.", "example": "64 entries × 4 KiB covers 256 KiB; 64 entries × 2 MiB covers 128 MiB, ignoring associativity conflicts.", "fq": "Why are TLB shootdowns expensive?", "fa": "They interrupt other CPUs and wait for invalidation acknowledgments; frequent shared-address-space remaps scale poorly."}, {"track": "os", "slug": "emat", "title": "Effective memory access time", "idea": "Compute a weighted average over mutually exclusive paths. State whether lookup overlaps memory access and how many page-table levels a miss reads. Page-fault service is a separate rare but expensive path.", "problem": "A candidate adds one memory access to every path twice, or mixes nanoseconds with milliseconds, producing an implausible EMAT.", "steps": ["List hit and miss path latencies with units", "Multiply each path by its probability", "Sum and check that the result lies between path latencies"], "trade": "TLB capacity and page size reduce miss probability, but huge pages may trade fragmentation for speed.", "example": "Serial TLB 10 ns, memory 100 ns, one-level resident table, hit 90%: 0.9×110 + 0.1×210 = 120 ns.", "fq": "How does a tiny major-fault probability affect the average?", "fa": "A millisecond-scale path can dominate nanosecond hits. Convert units before multiplying probabilities."}, {"track": "os", "slug": "page-faults", "title": "Page faults: minor, major and protection", "idea": "A page fault is a synchronous exception on translation or permission failure. The kernel checks the virtual-memory area and access intent before deciding to allocate, load, copy, or reject. Not all faults perform disk I/O.", "problem": "A service forks and writes many shared pages. Fault count rises, but disk reads remain flat: these are copy-on-write/minor faults.", "steps": ["Validate address and attempted access against mappings", "Resolve demand-zero/COW/resident backing or initiate storage I/O", "Update PTE, invalidate as needed, and retry the faulting instruction"], "trade": "Demand paging saves upfront work but shifts latency to first access; prefaulting improves predictability at a memory cost.", "example": "A first write to an anonymous zero page allocates a private frame; reading an evicted file page may require storage I/O.", "fq": "What distinguishes a minor fault from a TLB miss?", "fa": "A minor fault enters the kernel to repair a mapping without storage I/O; a TLB miss may be resolved entirely by hardware."}, {"track": "os", "slug": "page-replacement", "title": "FIFO, LRU, OPT and Clock", "idea": "Replacement selects a resident victim when a fault needs a frame. FIFO uses arrival time, LRU uses recency, OPT uses future knowledge, and Clock approximates recency with reference bits. Count hits and faults under stated initial conditions.", "problem": "A streaming scan evicts frequently reused hot pages, making a second hot-data access fault repeatedly.", "steps": ["On every reference first test residency", "On a miss choose a victim using the policy's state", "Load the page and update arrival/recency/reference metadata"], "trade": "Exact LRU bookkeeping is costly; Clock is practical but approximate; OPT is an offline comparison bound.", "example": "Empty 3 frames, FIFO, 1 2 3 1 4 1: hits only at fourth access; loading 4 evicts 1, so the final 1 faults. Total 5.", "fq": "Why must hits not refresh FIFO arrival order?", "fa": "FIFO tracks load order, not last use. Refreshing on a hit turns the policy into something else."}, {"track": "os", "slug": "belady-anomaly", "title": "Belady’s anomaly", "idea": "FIFO does not have the stack property: resident pages with n frames need not be a subset of those with n+1. A larger memory can therefore produce more faults on the same trace. LRU and OPT have the stack property.", "problem": "Increasing FIFO frames from 3 to 4 unexpectedly raises faults for a fixed reference string.", "steps": ["Run the identical trace with empty frames under each capacity", "Record FIFO victims without moving hit pages", "Compare fault totals and explain different resident sets"], "trade": "FIFO is simple but lacks monotonic performance; stack algorithms avoid this anomaly but may need more metadata.", "example": "Trace 1 2 3 4 1 2 5 1 2 3 4 5: FIFO gives 9 faults with 3 frames and 10 with 4.", "fq": "Does more RAM always make a real system slower under FIFO?", "fa": "No. The anomaly is trace-dependent; it demonstrates lack of a guarantee, not a universal trend."}, {"track": "os", "slug": "thrashing", "title": "Thrashing and working sets", "idea": "A working set is the pages used during a chosen recent window. If active working sets exceed available frames, faults evict pages needed again soon; useful CPU work collapses while paging dominates.", "problem": "Adding request workers increases resident demand; disk traffic spikes and throughput falls rather than rising.", "steps": ["Measure major faults, paging and runnable/blocked states", "Estimate active working sets rather than total virtual size", "Reduce concurrent memory demand or increase usable RAM"], "trade": "More concurrency hides I/O latency until memory pressure crosses a threshold; admission control may outperform replacement tweaks.", "example": "Four workers each need 300 MiB of hot pages on a 1 GiB budget: 1.2 GiB cannot stay resident together.", "fq": "Why can CPU utilization be low while latency is high?", "fa": "Workers sleep waiting for page-in I/O. Low CPU does not imply spare capacity in another resource."}, {"track": "os", "slug": "paging-segmentation", "title": "Paging vs segmentation", "idea": "Paging divides memory into equal-sized blocks and separates virtual contiguity from physical contiguity. Segmentation represents variable-sized logical regions with base/limit protection. Modern process layouts use logical regions but usually page them.", "problem": "A request for a contiguous 10 MiB segment fails despite 20 MiB total free memory scattered among small holes.", "steps": ["Identify whether translation uses page/offset or segment/offset", "Check fixed block mapping or segment base and limit", "Separate logical regions from the underlying physical allocation scheme"], "trade": "Paging avoids external fragmentation for base-page allocation but causes last-page internal waste; segmentation exposes logical boundaries but needs variable-sized holes.", "example": "A 5 KiB object using 4 KiB pages reserves 8 KiB: 3 KiB is unused inside allocated pages.", "fq": "Does paging remove all physical contiguous allocation problems?", "fa": "No. Huge pages and some device/DMA needs require larger contiguous blocks and can suffer fragmentation."}, {"track": "os", "slug": "fragmentation", "title": "Internal and external fragmentation", "idea": "Internal fragmentation is unused space inside an allocated block. External fragmentation is free space split into holes too small for a required contiguous allocation. Always identify the allocator layer and unit.", "problem": "A heap has 64 KiB free in scattered 4 KiB holes but cannot satisfy a 16 KiB contiguous heap allocation.", "steps": ["Compute requested vs granted block sizes", "Enumerate free hole sizes and adjacency", "Coalesce adjacent free blocks or change placement when supported"], "trade": "Size classes improve speed and metadata simplicity but round requests up; compaction can reclaim holes only if references can be updated.", "example": "A 33-byte request in a 64-byte class wastes 31 bytes internally; two separated 8-byte holes cannot satisfy one 12-byte block.", "fq": "Why can moving heap blocks be unsafe in C?", "fa": "Raw pointers may exist anywhere. A general allocator cannot reliably find and rewrite all references."}, {"track": "os", "slug": "allocators", "title": "Memory allocators and free lists", "idea": "An allocator manages reserved virtual memory using metadata, alignment, size classes and free structures. free returns a block to the allocator; returning physical/virtual memory to the OS is a separate policy.", "problem": "A double free inserts the same block twice into a free list, allowing two live allocations to alias the same memory.", "steps": ["Round size and alignment, select a suitable free block", "Split when the remainder can hold useful metadata and payload", "On free validate ownership and coalesce eligible neighbors"], "trade": "Per-thread arenas reduce lock contention but retain memory; aggressive release lowers RSS but adds system-call and fault cost.", "example": "First-fit holes 16, 40, 24 bytes and request 20: choose 40, leaving a 20-byte remainder under a zero-metadata teaching model.", "fq": "Why can RSS stay high after free?", "fa": "Arenas retain reusable pages, or one small live allocation keeps an entire page resident."}, {"track": "os", "slug": "epoll", "title": "select, poll and epoll", "idea": "Readiness APIs report operations likely to proceed without blocking, not completed I/O. select scans bitsets, poll scans arrays, epoll keeps a registered interest set and returns events. Edge-triggered use requires draining until EAGAIN.", "problem": "An edge-triggered handler reads once and leaves buffered bytes unread; no new edge arrives, so the connection stalls.", "steps": ["Register a nonblocking descriptor and desired events", "Process returned readiness while handling close/error states", "For edge-triggered reads loop until EAGAIN, EOF or a fatal error"], "trade": "Persistent interest scales idle-heavy workloads; level triggering is easier to reason about; edge triggering can reduce notifications but needs careful draining.", "example": "recv returns 512 then 512 then EAGAIN. A correct edge handler consumes both chunks before waiting again.", "fq": "Is epoll always O(1) overall?", "fa": "No. Registration, ready-event processing, user work and kernel data structures have costs; the useful distinction is avoiding a full idle-descriptor scan."}, {"track": "os", "slug": "inodes-links", "title": "Inodes, files and links", "idea": "A pathname is a directory lookup sequence. A directory entry maps a name to an inode; the inode holds metadata and block references. Open descriptors point through open-file descriptions, so unlink removes a name without invalidating an open file.", "problem": "A deleted log file still occupies disk because a running process retains an open descriptor.", "steps": ["Resolve each directory component with permissions", "Use the inode to open an object and maintain a reference", "Unlink drops a directory link; reclaim only after links and open references permit it"], "trade": "Hard links share inode identity within a filesystem; symlinks name a path and can cross filesystems but may dangle.", "example": "Open file, unlink its only name, then read from the descriptor: data remains accessible until references close.", "fq": "Why do dup'd descriptors share an offset?", "fa": "They refer to the same open-file description; independent open calls ordinarily get separate offsets."}, {"track": "os", "slug": "execution-path", "title": "Path lookup and ./a.out execution", "idea": "The shell parses a command, resolves its path, creates a child and invokes execve. ./a.out explicitly starts at the current directory, not PATH. The kernel validates execute permission and format, maps the image and prepares startup state.", "problem": "A binary exists but execution says not found because its ELF interpreter path is missing, not because the file itself is absent.", "steps": ["Resolve ./a.out relative to current working directory", "Validate executable file and inspect ELF or shebang interpreter", "Map segments, build argv/environment/auxiliary data and transfer to the entry point"], "trade": "Dynamic linking saves duplication but adds dependency and startup work; static linking improves portability at larger image size.", "example": "A shell command a.out searches PATH; ./a.out bypasses that search. A script shebang names an interpreter that must also exist.", "fq": "Does exec create a new PID?", "fa": "No. It replaces the calling process image; fork/spawn creates a distinct process."}, {"track": "os", "slug": "cpu-caches", "title": "CPU caches and false sharing", "idea": "Caches move data in cache-line units. False sharing occurs when different threads update independent variables on the same line, repeatedly transferring ownership through coherence even without logical sharing.", "problem": "Two per-thread counters scale worse on two cores than one because they occupy a single cache line.", "steps": ["Map hot writes to cache-line boundaries", "Observe repeated ownership transfers under concurrency", "Separate independently written state or batch local updates"], "trade": "Padding lowers coherence traffic but increases memory footprint and can reduce cache density.", "example": "Assume 64-byte lines: counters at offsets 0 and 8 share a line; placing them on separate aligned lines avoids this specific false sharing.", "fq": "Does volatile prevent false sharing?", "fa": "No. volatile neither separates addresses nor implements inter-thread atomicity or synchronization."}, {"track": "os", "slug": "numa", "title": "NUMA placement", "idea": "NUMA machines have memory attached to nodes; a CPU can access remote memory but with higher latency and lower effective bandwidth. First-touch allocation often places pages near the CPU that faults them in, subject to policy.", "problem": "One initialization thread touches every page on node 0; workers on node 1 then perform remote accesses all day.", "steps": ["Identify CPU affinity and memory node placement", "Initialize/touch pages near the workers that will use them", "Measure locality and rebalance only with workload evidence"], "trade": "Pinning improves locality but reduces scheduling flexibility; interleaving spreads bandwidth but increases some access latency.", "example": "Two worker groups each own 1 GiB: local first touch can avoid making one node's memory controller the bottleneck.", "fq": "Why can migration fail to help?", "fa": "Pages may remain on the old node, sharing patterns may dominate, or the task may migrate again before costs amortize."}, {"track": "os", "slug": "event-loops", "title": "Event loops and asynchronous state", "idea": "An event loop multiplexes many logical operations on a small number of threads. Each readiness/completion callback advances a state machine. Long CPU work or blocking calls monopolize the loop and delay unrelated connections.", "problem": "A callback performs a 200 ms blocking disk read; every socket assigned to that loop experiences a latency spike.", "steps": ["Wait for readiness/completion and timers", "Advance per-connection state without blocking", "Offload long work and resume through queued completion with bounded admission"], "trade": "Few threads reduce switches and memory, but state-machine complexity, fairness and backpressure become explicit responsibilities.", "example": "Ten thousand idle sockets need not mean ten thousand runnable threads; only ready work should consume loop time.", "fq": "How do you prevent one connection from monopolizing a loop?", "fa": "Set per-event byte/work budgets and reschedule unfinished work while keeping protocol state intact."}, {"track": "os", "slug": "os-debugging", "title": "OS performance diagnosis", "idea": "Start with the saturated resource and a reproducible symptom, not a favorite tuning flag. Compare CPU time, runnable queue, blocked waits, memory faults and storage latency. Averages alone hide tail behavior.", "problem": "CPU is 20%, p99 is 2 seconds, and workers block on one lock; adding cores does not fix serialization.", "steps": ["Separate service time from queueing and blocked time", "Correlate perf/strace/proc evidence with the slow interval", "Change one suspected cause and compare the same workload"], "trade": "Instrumentation adds overhead; sampling is cheaper but can miss rare events, while full tracing supplies detail at cost.", "example": "High futex wait time plus a shared critical section points to contention; high major faults plus I/O wait points elsewhere.", "fq": "Why is load average not CPU utilization?", "fa": "Linux load includes runnable tasks and tasks in uninterruptible sleep; it can rise during I/O stalls."}, {"track": "os", "slug": "security-boundaries", "title": "Security boundaries and privilege", "idea": "Hardware privilege, page permissions, credentials and syscall validation work together. A process boundary is not automatically a complete sandbox; inherited descriptors and privileges are capabilities that may survive execution.", "problem": "A restricted child inherits an open privileged file descriptor and reads data it could not open by pathname.", "steps": ["Identify credentials, namespaces, capabilities and inherited descriptors", "Drop unnecessary privilege and close or mark descriptors CLOEXEC", "Validate all cross-boundary arguments and enforce least privilege"], "trade": "Isolation layers reduce blast radius but add operational and communication overhead; one layer should not be assumed sufficient.", "example": "FD_CLOEXEC prevents a sensitive descriptor leaking into a successfully exec'd helper; it does not close the parent copy.", "fq": "Why do namespaces alone not guarantee security?", "fa": "They virtualize views of resources; permission checks, capabilities and attack surface still need control."}, {"track": "os", "slug": "boot-startup", "title": "Boot and process startup", "idea": "Firmware hands control to a bootloader or kernel; the kernel initializes memory, devices and scheduling before starting user space. Program startup then maps an executable and runtime dependencies before main. These are different layers.", "problem": "A service never reaches main because dynamic loader initialization fails; debugging only application logic misses the failure.", "steps": ["Kernel establishes hardware and core subsystems", "Start init/service management and launch the process", "Runtime entry prepares language state then invokes main"], "trade": "More initialization can improve runtime readiness but increases cold-start latency and failure dependencies.", "example": "ELF entry typically runs runtime startup rather than main directly; constructors may execute before main.", "fq": "Why distinguish boot time from process startup time?", "fa": "They have different owners and dependencies; repeatedly starting workers does not reboot the kernel."}, {"track": "os", "slug": "linux-reasoning", "title": "Practical Linux reasoning", "idea": "Use observations to test a hypothesis: ps/top show task state, /proc exposes process data, strace shows syscalls, perf samples CPU activity, and ss shows sockets. A command's output is evidence, not a diagnosis by itself.", "problem": "strace shows repeated short reads. Calling it packet loss is unjustified because stream reads can legally be partial.", "steps": ["State the symptom and layer under investigation", "Choose a tool that observes that layer with acceptable overhead", "Correlate evidence and reproduce before making a causal claim"], "trade": "Tracing adds precision but can perturb timing; low-overhead counters are broad and require context.", "example": "A D-state task with long storage operations suggests uninterruptible I/O waits; it is not proof of CPU saturation.", "fq": "When is strace insufficient?", "fa": "It misses user-space CPU work and may alter timing; use sampled stacks and scheduler evidence for those cases."}, {"track": "os", "slug": "system-calls", "title": "System calls and error contracts", "idea": "A syscall crosses a controlled privilege boundary to request kernel service. Its wrapper converts kernel return conventions into language/library errors. Partial success, interruption and retry rules depend on the operation.", "problem": "A program assumes write sends its entire buffer and silently drops the unsent suffix after a short write.", "steps": ["Validate arguments and enter the kernel through the supported ABI", "Perform as much work as the call contract permits", "Interpret byte counts/errors and retry only under the operation's rules"], "trade": "Batching amortizes boundary cost but can increase buffering latency and memory use.", "example": "write returns 300 for a 1000-byte buffer: advance pointer by 300, retain 700, and handle later errors without duplicating bytes.", "fq": "Does every libc function invoke a syscall?", "fa": "No. Pure computation and many cached/vDSO paths stay in user space."}, {"track": "os", "slug": "scheduling-numericals", "title": "Scheduling numericals and conventions", "idea": "Completion time is when a job finishes; turnaround is completion minus arrival; waiting is turnaround minus CPU burst in a single-burst no-I/O model. Response is first dispatch minus arrival. State ties and arrival-at-quantum-end rules.", "problem": "Two RR solutions differ because one queues new arrivals before the expired job and the other does the reverse.", "steps": ["Write arrivals, bursts, tie rules and quantum", "Build the timeline including idle gaps and preemptions", "Derive per-job metrics from the completed timeline"], "trade": "A short quantum improves initial response but increases switch overhead; averages can hide starvation or outliers.", "example": "FCFS: P1 arrives 0/burst 5, P2 arrives 1/burst 2. Completion 5,7; waits 0,4; mean waiting 2.", "fq": "Can SJF always run the globally shortest job?", "fa": "Only among arrived, eligible jobs; knowing future bursts or arrivals is an assumption, not a free capability."}, {"track": "os", "slug": "deadlock-strategies", "title": "Deadlock prevention, avoidance and detection", "idea": "Prevention structurally breaks a Coffman condition; avoidance grants requests only if the state stays safe; detection allows risky allocation then finds and recovers deadlocks. These answer different operational needs.", "problem": "A system labels timeouts as prevention, but timed-out tasks still retain resources and the cycle remains.", "steps": ["Model ownership, pending requests and resource multiplicity", "Select prevention/avoidance/detection with explicit assumptions", "Define cleanup and recovery for failed or cancelled operations"], "trade": "Prevention can reduce utilization; avoidance needs maximum claims; detection may require killing work and rolling back effects.", "example": "A global lock order prevents circular wait; a wait-for graph detects cycles only under its modeled resource assumptions.", "fq": "Why is a cycle not sufficient for multi-instance resource deadlock?", "fa": "An instance may be released by a process outside the cycle. Use allocation/request counts and completion reasoning."}, {"track": "os", "slug": "atomics-lockfree", "title": "Atomics and lock-free reasoning", "idea": "Atomic operations avoid torn/interleaved access to the atomic object, but a multi-object invariant still needs a protocol. Lock-free guarantees system-wide progress, not that every thread finishes promptly. Memory reclamation is separate.", "problem": "A stack pop CAS succeeds but a concurrent thread already freed the observed node: atomic head updates did not make dereferencing safe.", "steps": ["Identify the operation's linearization point", "Handle CAS failure and ordering requirements", "Prove node lifetime using hazard pointers, epochs or another valid scheme"], "trade": "Lock-free structures can reduce blocking but increase retries, complexity and reclamation latency.", "example": "Two CAS attempts compete on head: one succeeds, the other must reread and retry rather than reuse a stale next pointer.", "fq": "How does wait-free differ from lock-free?", "fa": "Wait-free gives a bounded number of steps per operation; lock-free only ensures some operation progresses."}, {"track": "cn", "slug": "dns-caching", "title": "DNS caching and TTL", "idea": "Resolvers cache positive and negative answers under TTL rules. TTL is a cache lifetime, not a promise every client sees an update at one instant. Delegation and connection/application caching can extend operational effects.", "problem": "A DNS record changes but traffic still reaches the old IP because cached answers and existing pooled connections remain.", "steps": ["Check the exact queried record and resolver", "Inspect remaining TTL and authoritative answer", "Separate DNS cache lifetime from existing connection reuse"], "trade": "Long TTL reduces upstream work and improves resilience to brief authority outages; short TTL improves update agility at more lookup cost.", "example": "A cached answer has 120 seconds remaining at migration time; lowering the authoritative TTL now cannot retroactively shorten that stored lifetime.", "fq": "Why might NXDOMAIN persist after creating a name?", "fa": "Negative caching uses authority-provided limits; the resolver may not query again until that cache entry expires."}, {"track": "cn", "slug": "arp", "title": "ARP and next-hop resolution", "idea": "IPv4 routing chooses a next-hop IP before ARP resolves that next hop to a local link address. For a remote destination, ARP asks for the gateway's MAC, not the remote host's MAC. IPv6 uses Neighbor Discovery instead.", "problem": "A host repeatedly ARPs for a remote public address because its subnet mask incorrectly marks that address as local.", "steps": ["Apply the route to select direct destination or gateway", "Lookup or broadcast for the next-hop MAC on the local link", "Encapsulate the IP packet in a frame for that next hop"], "trade": "Caching avoids broadcasts but stale/poisoned entries misdirect frames; authentication is not built into ordinary ARP.", "example": "10.0.0.2/24 reaching 192.0.2.9 via 10.0.0.1 uses gateway MAC in Ethernet while preserving destination IP 192.0.2.9.", "fq": "Does a router preserve the Ethernet addresses?", "fa": "No. Each routed hop builds a new link-layer frame and decrements IP TTL."}, {"track": "cn", "slug": "ethernet", "title": "Ethernet and MAC learning", "idea": "A switch learns source MAC-to-port mappings from incoming frames. Known unicast forwards to one port; unknown unicast and broadcast flood within the VLAN except ingress. Learning is not IP routing.", "problem": "A looped L2 topology circulates flooded frames indefinitely and repeatedly destabilizes MAC learning.", "steps": ["Learn the source MAC on the ingress port", "Lookup destination MAC within the VLAN", "Forward, flood or filter according to the table and topology controls"], "trade": "Learning simplifies plug-and-play but broadcast domains need bounds and loop prevention.", "example": "A sends to unknown B: switch learns A's port and floods. B replies: switch learns B and can unicast subsequent traffic.", "fq": "Why does Ethernet need loop prevention?", "fa": "Ordinary Ethernet frames have no routed TTL; redundant active loops can amplify floods."}, {"track": "cn", "slug": "hub-switch-router", "title": "Hub vs switch vs router", "idea": "A hub repeats signals, a switch forwards link-layer frames, and a router forwards packets between IP networks. Distinguish collision domains, broadcast domains and lookup keys instead of only saying layer numbers.", "problem": "A broadcast crosses every switch port in a VLAN but does not ordinarily pass a router to another subnet.", "steps": ["Identify the device's forwarding unit", "Identify the lookup key: none, MAC, or IP prefix", "Determine which boundaries isolate collisions and broadcasts"], "trade": "Switches offer cheap local forwarding; routers provide network boundaries and policy at more configuration complexity.", "example": "Three hosts on a hub share collision behavior; switch ports separate those links, while one VLAN remains a broadcast domain.", "fq": "Can a switch route?", "fa": "A multilayer switch may implement routing too; describe the active function rather than relying on the box's label."}, {"track": "cn", "slug": "ip-addressing", "title": "IP addressing and local delivery", "idea": "An IP address plus prefix defines an interface's on-link network, not a permanent identity for a device. Routing selects how to reach an address. Private and documentation ranges are not globally routable ordinary host destinations.", "problem": "Two hosts configured with inconsistent masks disagree about whether to send directly or through a gateway.", "steps": ["Calculate the network prefix using the mask", "Select a route and source interface/address", "Resolve the selected next hop and send with valid scope"], "trade": "Address aggregation shrinks routing tables but reduces placement freedom; private addressing needs a separate public connectivity plan.", "example": "10.1.2.3/24 and 10.1.2.200/24 are on the same prefix; 10.1.3.3 requires another route.", "fq": "Why is IP not a MAC address?", "fa": "IP is a network-layer locator used across routed links; MAC addresses serve local link delivery."}, {"track": "cn", "slug": "subnetting", "title": "Subnetting and host capacity", "idea": "Borrowing host bits creates smaller aligned prefixes. Conventional IPv4 LAN usable capacity is 2^(32-prefix) minus network and broadcast, with /31 point-to-point and /32 special conventions. State the convention.", "problem": "An address plan assigns a /27 for 40 hosts and discovers only 30 conventional usable addresses.", "steps": ["Compute required addresses including reserved endpoints", "Choose the smallest power-of-two aligned block that fits", "Derive network, broadcast and host range"], "trade": "Smaller blocks save addresses but restrict growth; larger blocks waste space and enlarge broadcast scope.", "example": "40 hosts need 64 total addresses, so /26 supplies 62 conventional usable hosts.", "fq": "Why must subnet boundaries be aligned?", "fa": "Prefix matching fixes high-order bits; an arbitrary starting address may straddle two different prefixes."}, {"track": "cn", "slug": "vlsm", "title": "VLSM allocation", "idea": "Variable-length subnetting assigns different aligned block sizes inside a parent prefix. Allocate largest requirements first to reduce stranded alignment gaps. Distinguish requested hosts from total block addresses.", "problem": "Small early allocations fragment a parent block and leave no aligned region for the largest subnet.", "steps": ["Sort subnet requirements by descending block size", "Allocate the next aligned prefix that fits each requirement", "Check parent containment and non-overlap"], "trade": "Efficient packing conserves addresses but leaves limited contiguous room for future expansion.", "example": "Within 10.0.0.0/24: 100 hosts gets .0/25; 50 gets .128/26; 20 gets .192/27, leaving .224/27.", "fq": "Is VLSM only arithmetic?", "fa": "No. Growth margins, broadcast needs and operational boundaries influence the plan too."}, {"track": "cn", "slug": "longest-prefix", "title": "Longest-prefix matching", "idea": "Forwarding selects the most specific matching destination prefix, then applies route selection rules within that prefix. Numeric metric does not make a less-specific route beat a more-specific route.", "problem": "An operator lowers the default route's metric but traffic still follows an installed /24 route.", "steps": ["Test the destination against candidate prefix masks", "Choose the match with the greatest prefix length", "Resolve the selected next hop and applicable policy"], "trade": "More-specific routes enable precision but grow state and can redirect traffic unexpectedly.", "example": "Routes /0→A, 10.0.0.0/8→B, 10.2.0.0/16→C: 10.2.3.4 goes C.", "fq": "What if two routes have the same prefix length?", "fa": "Use the platform's preference/metric/ECMP rules; longest prefix alone does not select among equals."}, {"track": "cn", "slug": "shortest-path", "title": "Shortest-path routing reasoning", "idea": "Link-state routing models a graph of nonnegative costs and computes shortest paths to destinations. Dijkstra settles the currently smallest tentative distance and relaxes outgoing edges. A shortest route is not necessarily fewest hops.", "problem": "A two-hop route costs 12 while a three-hop route costs 6; choosing fewest hops violates the configured cost objective.", "steps": ["Initialize source distance zero and others infinity", "Settle the smallest tentative unvisited distance", "Relax neighbors and retain predecessor/next-hop information"], "trade": "Metric optimization improves modeled cost, but stale state and unmodeled congestion can still cause poor performance.", "example": "A-B=2, B-C=2, A-C=7: shortest A→C is A→B→C cost 4.", "fq": "Why does convergence matter after failure?", "fa": "Routers update at different times; transient inconsistent forwarding can loop or blackhole packets."}, {"track": "cn", "slug": "tcp-sequence", "title": "TCP sequence numbers and ACKs", "idea": "Sequence numbers count stream bytes modulo 2^32. The cumulative ACK is the next byte expected, not the most recently received byte. SYN and FIN each consume one sequence number; pure ACKs do not.", "problem": "A receiver gets later data across a gap and advances its cumulative ACK anyway, wrongly implying the missing prefix arrived.", "steps": ["Establish initial sequence spaces in the handshake", "Track contiguous received bytes separately from out-of-order blocks", "ACK the first missing byte and optionally SACK later blocks"], "trade": "Cumulative ACK is simple and robust; SACK adds recovery precision and state.", "example": "ISN 100, SYN consumes 100. Data 101–200 gives ACK 201; later 301–400 still ACK 201 until 201–300 arrives.", "fq": "Is an ACK proof the application committed a payment?", "fa": "No. TCP ACK confirms receipt in the peer's transport stack, not application processing or durable business effect."}, {"track": "cn", "slug": "partial-recv", "title": "Partial recv and stream framing", "idea": "TCP delivers ordered bytes without preserving send-call boundaries. recv may return any available positive prefix up to the requested size. Application framing must survive splitting, coalescing, EOF and malformed lengths.", "problem": "A receiver parses each recv buffer as one JSON message; a split or two combined messages break parsing.", "steps": ["Accumulate bytes into bounded parser state", "Read and validate a length prefix or delimiter framing rule", "Extract complete frames and retain an incomplete suffix"], "trade": "Length prefixes support binary payloads but require bounds checks; delimiters need escaping and incremental search.", "example": "A 4-byte length 6 arrives as 2+2 bytes, payload as 1+5. The parser emits one six-byte message only after all bytes arrive.", "fq": "What does recv returning zero mean?", "fa": "For a stream with a nonzero requested length, orderly peer shutdown/EOF; it is not EAGAIN."}, {"track": "cn", "slug": "flow-control", "title": "TCP receiver flow control", "idea": "The receiver advertises rwnd to limit unacknowledged bytes it can buffer. The sender is limited by both receiver capacity and congestion capacity, minus bytes already in flight. Zero window means pause, not close.", "problem": "A slow application stops draining its socket; advertised window shrinks and the sender stalls despite an uncongested path.", "steps": ["Receiver drains data and updates available buffer window", "Sender computes permitted outstanding bytes from min(rwnd,cwnd)", "Handle zero-window probes so a lost update does not stall forever"], "trade": "Large buffers absorb bursts but consume memory and can hide slow consumers; backpressure preserves bounds.", "example": "rwnd 64 KiB, cwnd 16 KiB, in-flight 12 KiB: at most 4 KiB additional data under this simplified model.", "fq": "Why is rwnd not congestion control?", "fa": "It reflects receiver buffering, not bottleneck router queues or shared network capacity."}, {"track": "cn", "slug": "slow-start", "title": "TCP slow start", "idea": "Classic teaching slow start increases cwnd by about one MSS per ACK, approximately doubling per RTT when each segment is ACKed and the flow is window-limited. State the initial window and threshold rather than assuming modern defaults.", "problem": "A solution doubles forever even after reaching ssthresh, overestimating available sending capacity.", "steps": ["Start with the stated initial cwnd", "Grow according to ACKs while below ssthresh", "Switch to congestion avoidance or respond to a loss event"], "trade": "Rapid growth discovers capacity quickly but can overshoot queues; pacing and modern variants change packet-level behavior.", "example": "Teaching model IW=1 MSS, threshold 8: round-start windows 1,2,4,8 then 9 in additive avoidance.", "fq": "Why is the name slow misleading?", "fa": "It is slow relative to sending at full rate immediately; its initial growth is exponential rather than linear."}, {"track": "cn", "slug": "tahoe-reno", "title": "Tahoe, Reno and loss events", "idea": "Classic Tahoe resets cwnd to one MSS after loss. Reno uses fast retransmit/recovery after three duplicate ACKs but resets after timeout. Distinguish fast-recovery transient inflation from the later steady window.", "problem": "A learner treats every Reno loss as halving only, ignoring a timeout caused by insufficient duplicate ACKs.", "steps": ["Classify timeout versus duplicate-ACK recovery", "Set ssthresh using the specified flight/cwnd teaching convention", "Apply the selected algorithm and trace subsequent ACK-driven growth"], "trade": "Reno recovers single losses efficiently but multiple losses and reordering complicate it; SACK/NewReno improve recovery.", "example": "Simplified cwnd 16 MSS at triple-duplicate event: ssthresh 8, post-recovery Reno 8, Tahoe 1. Timeout resets both to 1.", "fq": "Why can packet reordering cause a false loss inference?", "fa": "Duplicate ACKs show a gap, not its cause; delayed rather than lost bytes can create the same signal."}, {"track": "cn", "slug": "cwnd-numericals", "title": "cwnd and bandwidth-delay numericals", "idea": "A window-limited rate is window bytes divided by RTT seconds, capped by link and receiver capacity. BDP is bandwidth times RTT with bit-to-byte conversion. Define whether a round label means start or end.", "problem": "A calculation treats Mbps as megabytes per second and overstates throughput by eight.", "steps": ["Convert windows and link rates into consistent units", "Compute min(cwnd,rwnd) divided by RTT", "Apply bottleneck limits and state ignored overhead/loss"], "trade": "Larger windows fill long-fat pipes but consume memory and can add queueing; capacity alone is not latency.", "example": "cwnd 20,000 B, RTT 0.1 s → 200,000 B/s = 1.6 Mbps, before headers and loss.", "fq": "What if the receiver window is smaller?", "fa": "Use rwnd as the cap; raising cwnd alone cannot overcome receiver backpressure."}, {"track": "cn", "slug": "rtt-rto", "title": "RTT estimation and RTO", "idea": "RTT varies, so timeout uses a smoothed estimate plus variation and implementation bounds. Retransmitted data can make an ACK ambiguous unless timestamps or other information disambiguate the measurement. Exponential backoff prevents aggressive repeated retries.", "problem": "A fixed 20 ms timeout on a 100 ms path triggers needless retransmissions and amplifies load.", "steps": ["Measure eligible samples and update smoothed RTT/variation", "Compute RTO with timer granularity and minimum rules", "Back off on timeout and avoid ambiguous retransmission samples"], "trade": "Short timers recover fast but cause spurious retransmits; long timers reduce false alarms but worsen failure latency.", "example": "Simplified SRTT 100 ms, RTTVAR 20 ms: SRTT+4×RTTVAR = 180 ms before bounds/granularity.", "fq": "Why exclude ambiguous samples after retransmission?", "fa": "An ACK may acknowledge the original or retransmitted copy, so elapsed time does not identify a unique RTT."}, {"track": "cn", "slug": "time-wait", "title": "TIME_WAIT and close states", "idea": "The active closer normally waits long enough to retransmit the final ACK and let old segments expire. Half-close allows one direction to end while the other remains open. CLOSE_WAIT usually means the local application has not closed after peer FIN.", "problem": "A client creates short connections to one destination and exhausts ephemeral tuples while the server accumulates CLOSE_WAIT from missing close calls.", "steps": ["Trace FIN/ACK separately in each direction", "Identify which side performs the active close", "Inspect state counts and descriptor/port lifecycle before tuning reuse"], "trade": "Pooling reduces setup and tuple churn but retains connections and needs stale-connection handling.", "example": "Teaching budget 30,000 ephemeral ports and 60-second reuse delay to one destination implies roughly 500 new connections/s.", "fq": "Is TIME_WAIT duration universally 2 minutes?", "fa": "No. MSL/state timer behavior is implementation-specific; give the supplied duration in numericals."}, {"track": "cn", "slug": "udp", "title": "UDP datagrams and application reliability", "idea": "UDP preserves datagram boundaries but does not guarantee delivery, ordering or uniqueness. A receiver buffer too small may truncate a datagram according to API/platform rules. Applications still need congestion responsibility.", "problem": "A game sends stale position packets reliably and blocks fresh updates behind old data, sacrificing timeliness.", "steps": ["Define message semantics and loss tolerance", "Bound datagram size and account for MTU", "Add only needed sequence, expiry, retry and congestion behavior"], "trade": "Selective reliability lowers latency but shifts protocol correctness to the application.", "example": "Positions numbered 10,11,12 arrive 12 then 11. A newest-state protocol discards 11 rather than waiting for all history.", "fq": "Does UDP inherently make an application faster?", "fa": "No. Performance depends on semantics, path, protocol design and loss handling; UDP offers fewer transport services."}, {"track": "cn", "slug": "http1", "title": "HTTP/1.1 persistence", "idea": "HTTP/1.1 can reuse a TCP connection for successive requests. Message framing comes from protocol rules such as Content-Length and chunked encoding, not recv boundaries. Pipelining responses remain ordered, so a slow response can block later ones.", "problem": "A client reads until socket close on a persistent response and waits forever even though Content-Length was satisfied.", "steps": ["Parse start line and headers incrementally", "Select the applicable body-framing rule", "Consume exactly the framed body and retain bytes for the next message"], "trade": "Persistence saves handshakes but retains resources; pipelining has application-level head-of-line issues.", "example": "Three sequential requests on one warm connection avoid three new TCP/TLS setups but still have request/response timing.", "fq": "Why is an HTTP message not one TCP packet?", "fa": "Transport segmentation and buffering are independent of HTTP framing."}, {"track": "cn", "slug": "http2", "title": "HTTP/2 multiplexing", "idea": "HTTP/2 frames multiplex independent stream IDs over one ordered TCP connection and compress headers. Responses can interleave, avoiding HTTP/1.1 response-order blocking, but missing TCP bytes still hold back all later transport bytes.", "problem": "One lost TCP segment delays delivery across many active HTTP/2 streams despite their independent stream IDs.", "steps": ["Establish HTTP/2 and stream framing", "Interleave frames while obeying per-stream/connection flow control", "Handle TCP loss and protocol stream errors at their respective layers"], "trade": "Multiplexing reduces connection count but shares congestion and TCP loss fate; too many streams can overload a backend.", "example": "A slow 200 ms response and fast 20 ms response can complete out of request order on separate streams, absent loss.", "fq": "Does HTTP/2 eliminate every kind of HOL blocking?", "fa": "No. It removes HTTP/1.1 ordering constraints across streams but not TCP byte-stream head-of-line blocking."}, {"track": "cn", "slug": "http3", "title": "HTTP/3 over QUIC", "idea": "HTTP/3 maps HTTP semantics onto QUIC streams. QUIC provides reliable per-stream delivery over UDP, so a missing byte in one stream need not block unrelated streams. Shared congestion and packet dependencies still couple performance.", "problem": "An operator expects HTTP/3 to work through a network that blocks UDP/443; connection setup fails and fallback matters.", "steps": ["Establish QUIC with integrated TLS", "Send HTTP data on independent QUIC streams", "Handle loss, migration, flow control and fallback under actual path policy"], "trade": "Stream independence improves loss isolation; UDP reachability and user-space transport add deployment complexity.", "example": "Loss carrying only stream A's data blocks A's ordered delivery, not necessarily completed bytes on B.", "fq": "Can a packet loss affect multiple QUIC streams?", "fa": "Yes, a packet may carry frames for several streams, and congestion control is commonly shared."}, {"track": "cn", "slug": "cookies-sessions-jwt", "title": "Cookies, sessions and JWT", "idea": "A cookie is a browser transport/storage mechanism; a session ID references server-side state; a JWT is a signed claims format. Signing prevents tampering, not reading. Authentication design must address expiry, revocation, origin and CSRF/XSS exposure.", "problem": "A signed token is treated as encrypted and sensitive personal data is placed in readable claims.", "steps": ["Choose stateful session or validated token based on requirements", "Validate signature, algorithm, issuer, audience and time claims", "Protect transport/storage and define revocation and rotation"], "trade": "Stateless verification scales reads but complicates early revocation; server sessions centralize control but need available state.", "example": "Logging out of one browser does not invalidate a stolen still-valid JWT unless the design has a revocation strategy.", "fq": "Does HttpOnly solve CSRF?", "fa": "No. It limits script reads of cookies; automatically attached cookies still need CSRF-aware request design."}, {"track": "cn", "slug": "idempotency", "title": "Idempotency and duplicate requests", "idea": "An idempotent operation has the same intended effect when repeated, not necessarily the same response bytes. A payment idempotency key identifies a logical operation, with payload consistency and atomic result storage. Network retries alone cannot guarantee exactly-once business effects.", "problem": "The processor commits a charge but the response is lost. Retrying with a new key creates a second charge.", "steps": ["Assign one key to the logical operation and validate payload", "Atomically record in-progress/committed state with the effect", "On duplicate return/reconcile the recorded result rather than re-executing"], "trade": "Retention consumes storage and requires expiry policy; short retention reintroduces duplicate risk during delayed retries.", "example": "Same key K and same amount 100 must not charge twice; same key with amount 200 should reject a payload conflict.", "fq": "Why is TCP reliability insufficient?", "fa": "Transport delivery does not identify application-level retries across reconnects or guarantee durable commit semantics."}, {"track": "cn", "slug": "certificates", "title": "Certificates and hostname validation", "idea": "A certificate binds a public key to names under a chain of trust and validity constraints. Verification needs trusted roots, signatures, hostname, usage and time checks. A valid chain for another hostname is not sufficient.", "problem": "A client disables hostname verification to fix a certificate error and accepts a man-in-the-middle certificate for the wrong service.", "steps": ["Build and validate a chain to a trusted root", "Check target hostname, validity and intended key usage", "Apply configured revocation/rotation policy and fail safely"], "trade": "Strict validation protects identity but expiry/rotation failures impact availability; automate rotation rather than bypassing checks.", "example": "Connecting to api.example.com with a valid certificate only for www.example.com must fail name validation.", "fq": "Does encryption without identity checking stop MITM?", "fa": "No. It can encrypt to an attacker; authentication is what binds the peer to the expected identity."}, {"track": "cn", "slug": "crypto", "title": "Symmetric and asymmetric cryptography", "idea": "Symmetric keys encrypt bulk data efficiently; asymmetric signatures authenticate and key agreement establishes a shared secret. These are distinct primitives. TLS combines them rather than encrypting every application byte directly with a certificate key.", "problem": "A design reuses a fixed encryption nonce with the same AEAD key, breaking confidentiality or integrity despite a strong cipher.", "steps": ["Authenticate peer keys with the selected trust model", "Derive traffic keys through the handshake/key schedule", "Use AEAD with unique nonces and rotate keys per protocol rules"], "trade": "Asymmetric operations simplify trust establishment but cost more; symmetric bulk encryption is fast but needs careful key/nonce lifecycle.", "example": "An ephemeral key exchange can protect old traffic after later certificate-key compromise, under forward-secrecy assumptions.", "fq": "Is hashing encryption?", "fa": "No. Hashes are one-way digest functions; encryption is reversible with a key, while signatures authenticate origin/integrity."}, {"track": "cn", "slug": "reverse-proxy", "title": "Reverse proxies and forwarded identity", "idea": "A reverse proxy accepts client connections and forwards requests to upstream services. It can terminate TLS, balance traffic and enforce limits. Forwarded headers must be trusted only from controlled proxy hops.", "problem": "An app trusts client-supplied X-Forwarded-For and uses a forged value for access decisions.", "steps": ["Define trusted proxy boundaries and strip untrusted forwarding headers", "Route to a healthy upstream with bounded connect/request budgets", "Propagate trace context and return failures without blind duplicate side effects"], "trade": "Central termination simplifies policy but creates an availability dependency and can obscure original connection properties.", "example": "A client sends X-Forwarded-For: 127.0.0.1; the edge must replace/normalize it according to trusted-hop policy.", "fq": "How does an L4 balancer differ?", "fa": "It forwards transport connections without needing HTTP request parsing; L7 routing understands application messages."}, {"track": "cn", "slug": "mtu", "title": "MTU and segment sizing", "idea": "Link MTU limits the network packet a link can carry without link-specific handling. TCP MSS limits payload, so subtract IP/TCP headers and account for options/tunnels. Ethernet frame overhead is not part of the usual 1500-byte IP MTU.", "problem": "A tunnel adds 50 bytes but endpoints still send 1500-byte inner packets, producing oversized outer packets.", "steps": ["Identify path/interface MTU and encapsulation overhead", "Subtract actual IP and transport headers", "Choose a payload size that fits or discover a lower path limit"], "trade": "Small packets avoid size failures but increase header and processing overhead; larger payloads improve efficiency until the path limit.", "example": "MTU 1500, IPv4 20, TCP 20, no options: MSS 1460 bytes. A 50-byte tunnel lowers inner MTU to 1450.", "fq": "Why can advertised MSS differ by direction?", "fa": "Each side advertises its receive capability and paths/interfaces can be asymmetric."}, {"track": "cn", "slug": "fragmentation", "title": "IP fragmentation", "idea": "IPv4 may fragment when allowed; IPv6 routers do not fragment forwarded packets. IPv4 fragment offsets are in 8-byte units and destination reassembly needs all required fragments. Losing one fragment can lose the whole datagram.", "problem": "A fragmented UDP datagram crosses a lossy path; one missing fragment prevents delivering any application datagram.", "steps": ["Check MTU, DF flag and IP version", "Split permitted IPv4 payload with aligned nonfinal fragment sizes", "Reassemble at destination or timeout and discard incomplete data"], "trade": "Fragmentation permits larger datagrams but adds loss amplification, reassembly state and filtering difficulties.", "example": "IPv4 datagram 4020 bytes including 20-byte header, MTU 1500: payload fragments 1480,1480,1040; offsets 0,185,370.", "fq": "Why prefer application sizing to fragmentation?", "fa": "It avoids all-or-nothing reassembly and makes path behavior more predictable."}, {"track": "cn", "slug": "pmtud", "title": "Path MTU discovery", "idea": "PMTUD learns the smallest usable packet size along a route from errors or probing. IPv4 DF with ICMP fragmentation-needed and IPv6 packet-too-big are classic signals. Blocking these messages can create black holes.", "problem": "TCP handshake and small responses succeed but large TLS/application records stall because oversized packets vanish and ICMP feedback is blocked.", "steps": ["Send with the protocol's path-size discovery behavior", "Process valid too-big feedback or packetization-layer probes", "Reduce packet size and refresh knowledge when the route changes"], "trade": "Allowing feedback improves reliability but needs validation; probing avoids reliance on all ICMP yet adds discovery time.", "example": "A 1500-byte probe hits a 1400-byte link with DF set: sender needs a lower packet size, not repeated identical retries.", "fq": "Why is ping success insufficient?", "fa": "A small ping can fit where large packets cannot; size and DF/probing assumptions matter."}, {"track": "cn", "slug": "ping", "title": "ping and ICMP diagnosis", "idea": "ping tests ICMP echo reachability and observed timing, not application health. Lack of reply may mean filtering, rate limiting or path failure. Success does not validate TCP ports, TLS identity or business processing.", "problem": "An HTTPS endpoint refuses connections while ping works; treating echo as a service health check misses the failed listener.", "steps": ["Test echo with stated size/count and record loss/RTT", "Compare TCP connect and application-specific checks", "Locate differences rather than inferring total health from one protocol"], "trade": "ICMP is simple and useful but often filtered or deprioritized; application probes are more representative and costlier.", "example": "Echo returns in 10 ms, TCP port 443 resets: network IP reachability exists but the expected service is unavailable.", "fq": "Does an intermediate router's ping loss prove transit loss?", "fa": "No. Control-plane replies may be rate limited while forwarded traffic succeeds normally."}, {"track": "cn", "slug": "traceroute", "title": "traceroute and TTL", "idea": "Traceroute sends probes with increasing TTL/hop limit. Routers expiring them may send ICMP time-exceeded; destination behavior depends on probe type. Missing replies do not prove missing forwarding, and load balancing can vary paths.", "problem": "A middle hop displays stars but later hops respond; declaring that middle router down contradicts the evidence.", "steps": ["Send probes with TTL 1,2,3 and correlate replies", "Identify probe protocol and terminal response", "Interpret gaps, ECMP and asymmetric return paths cautiously"], "trade": "Hop visibility helps localize changes but control-plane policy and return paths limit certainty.", "example": "TTL 1 expires at the first router; TTL 2 at the second. A final UDP port-unreachable can identify arrival in classic UDP traceroute.", "fq": "Why can hop RTTs decrease farther along the path?", "fa": "Each reply uses its own processing and return path; displayed RTTs are not additive link latencies."}, {"track": "cn", "slug": "packet-journey", "title": "Packet journey end to end", "idea": "Application data is framed, encrypted, segmented, routed and link-encapsulated. Across routers IP destinations generally stay the same except translation/tunneling, while link addresses change. TTL decreases per routed hop.", "problem": "A candidate says the destination MAC remains the remote server's at every hop, overlooking local-link encapsulation.", "steps": ["Resolve name and select route/next hop", "Encapsulate transport/IP into local frames and forward across hops", "At destination validate transport, decrypt and parse application framing"], "trade": "Layering localizes responsibilities but cross-layer failures require correlating several kinds of evidence.", "example": "Laptop→gateway uses gateway MAC; gateway→ISP uses the next link's addressing; destination IP is preserved absent NAT.", "fq": "Where can a packet capture see plaintext HTTPS?", "fa": "Usually before encryption or after TLS termination, not as readable application content in an ordinary wire capture."}, {"track": "cn", "slug": "network-debugging", "title": "Network failure diagnosis", "idea": "Separate DNS, route/link, connect, TLS and application phases. A timeout has no unique cause. Collect timing, errors, captures and correlation identifiers before blaming a component.", "problem": "DNS resolves and TCP connects but TLS stalls; restarting DNS cannot repair a handshake/certificate or packet-size problem.", "steps": ["Measure each stage independently", "Compare client/server evidence and packet paths", "Test a narrow hypothesis under the same failure conditions"], "trade": "Full captures provide detail but have privacy/storage costs; targeted metadata is cheaper but may miss payload/framing bugs.", "example": "curl timings show fast lookup/connect and slow first byte after TLS: inspect server queueing and dependencies next.", "fq": "What would you capture for repeated retransmissions?", "fa": "Both endpoints if possible, ACK/sequence ranges, timing and interface drop counters; a one-sided trace cannot locate every loss."}, {"track": "cn", "slug": "connection-pooling", "title": "Connection pooling and keep-alive", "idea": "Pooling reuses established connections to reduce setup RTTs and tuple churn. Pools need bounded sizes, idle expiry, health handling and queue budgets. TCP keepalive, HTTP persistence and HTTP/2 multiplexing are different concepts.", "problem": "An unbounded pool overwhelms the upstream; an overly small pool queues requests while CPU and network appear idle.", "steps": ["Set pool capacity relative to upstream limits and workload", "Reuse valid connections with explicit idle/lifetime handling", "Bound waiting and retry only operations with safe semantics"], "trade": "Reuse improves latency but stale connections and uneven load persist; recycling helps freshness at handshake cost.", "example": "A cold TLS 1.3/TCP request pays about 2 setup RTTs; warm reuse removes them, not the application request RTT.", "fq": "Does TCP keepalive replace request deadlines?", "fa": "No. It detects some idle peer failures on its own timer; it is not an application latency budget."}, {"track": "cn", "slug": "nagle", "title": "Nagle and TCP_NODELAY", "idea": "Nagle coalesces small writes while unacknowledged data exists, subject to transport rules. TCP_NODELAY disables that coalescing, not all buffering. Interaction with delayed ACK can hurt small request/response latency.", "problem": "An app sends a one-byte header then waits after a small payload write; coalescing and delayed ACK produce a noticeable pause.", "steps": ["Inspect small writes and outstanding unacknowledged data", "Compare batching at application level versus TCP_NODELAY", "Measure latency and packet overhead under the actual workload"], "trade": "Disabling Nagle can lower small-message latency but increases tiny packets; batching is often a better throughput strategy.", "example": "Combining a small header and payload in one write/writev reduces fragmented application submissions without relying on timing.", "fq": "Does one write guarantee one packet after NODELAY?", "fa": "No. Segmentation, buffering and offload still apply; write boundaries are not packet boundaries."}, {"track": "cn", "slug": "payment-reliability", "title": "Payment timeout and retry reasoning", "idea": "A timeout creates uncertainty about outcome, not proof of failure. The application must distinguish before-send failure, in-flight ambiguity and known response. Durable idempotency, status reconciliation and bounded backoff manage the ambiguity.", "problem": "Server commits a debit, response is lost, client retries without the original key and debits twice.", "steps": ["Keep one operation key across attempts and validate the request payload", "Use atomic durable outcome recording around the business effect", "After ambiguity query status/reconcile and retry within a bounded policy"], "trade": "Long dedup retention reduces duplicate risk but costs storage; retries improve availability but can amplify outages.", "example": "Attempt K commits 100, reply lost; retry K returns the stored outcome. A fresh K2 is a new operation and may charge again.", "fq": "Can you promise exactly-once delivery over a failing network?", "fa": "No general transport promise removes uncertainty. State the business-effect guarantee and the storage/coordination assumptions precisely."}, {"track": "cn", "slug": "multi-region", "title": "Multi-region network reliability", "idea": "Regions introduce longer RTTs, independent failure domains and partitions. Routing failover does not guarantee data consistency or that in-flight operations were not committed. Define consistency and recovery objectives explicitly.", "problem": "DNS shifts retries to another region while dedup state has not replicated, allowing the same payment key to execute twice.", "steps": ["Define operation authority, replication and failover rules", "Model partition, stale routing and ambiguous in-flight requests", "Choose safe degradation/reconciliation when guarantees cannot be met"], "trade": "Synchronous coordination adds latency and can reduce availability during partitions; asynchronous replication risks stale state/lost recent writes.", "example": "A 150 ms inter-region RTT adds a coordination floor to a cross-region commit, before processing and queueing.", "fq": "Why does health-check failover not solve every outage?", "fa": "Checks may be stale or too shallow, clients cache routes, and state transfer/ownership can remain unresolved."}, {"track": "cn", "slug": "observability", "title": "Network observability", "idea": "Metrics summarize rates/distributions, logs record events, and traces connect work across boundaries. Use correlation IDs and stage timings to distinguish queueing, retries and remote execution. Protect sensitive data in all telemetry.", "problem": "Retries each receive a new trace identity, hiding that three backend calls came from one logical request.", "steps": ["Propagate trace and operation identity across hops", "Record DNS/connect/TLS/request budgets and retry counts", "Correlate latency distributions with errors and saturation at the same interval"], "trade": "High-cardinality detail aids diagnosis but costs storage and can leak data; sampling needs deliberate rare-error coverage.", "example": "A p99 spike with flat mean can be driven by a few retries or queues; a single average is insufficient.", "fq": "Why should idempotency key and trace ID be different concepts?", "fa": "One identifies business-operation identity, the other observation context; retries may have separate spans while sharing the operation key."}] as const;
export const expandedLessons: Lesson[] = topics.map((x) => ({
 track:x.track, slug:x.slug, title:x.title, short:x.idea.split('. ')[0]+'.',
 question:x.fq, problem:x.problem+'\n\nBefore choosing a fix, identify the state that is shared, the layer that owns it, and the observation that would distinguish a mechanism failure from a capacity limit.',
 idea:x.idea, how:{text:x.steps.map((s,i)=>`${i+1}. ${s}`).join('\n\n')+'\n\n'+x.idea, example:x.example},
 trace:x.steps.map((s,i)=>({label:`Step ${i+1}`,detail:s})),
 checks:[
 {id:x.slug+'-mechanism',kind:'typed',prompt:x.fq,accept:[x.fa],explain:x.fa,model:x.fa,why:x.idea,tradeoff:x.trade,followups:[{q:'Explain the mechanism step by step.',a:x.steps.join(' → ')},{q:'Defend your answer using the worked example.',a:x.example}]},
 {id:x.slug+'-order',kind:'order',prompt:`Order the mechanism for ${x.title.toLowerCase()}.`,items:[...x.steps],explain:x.steps.join(' → '),why:x.idea,tradeoff:x.trade},
 {id:x.slug+'-failure',kind:'scenario',prompt:x.problem+' Which response addresses the mechanism rather than hiding the symptom?',options:[x.steps[0], 'Increase concurrency without measuring the bottleneck.', 'Retry indefinitely without changing the failed precondition.', 'Assume the observed result proves the application is correct.'],answer:0,explain:x.steps.join(' → '),why:x.idea,tradeoff:x.trade,followups:[{q:x.fq,a:x.fa},{q:'What evidence would distinguish the failure from overload?',a:x.problem+' Check the mechanism states and the limiting resource before tuning.'}]},
 {id:x.slug+'-match',kind:'match',prompt:'Match the interview evidence to its role.',pairs:[['Mechanism',x.steps[1]],['Concrete example',x.example],['Trade-off',x.trade]],explain:'A strong answer separates how it works, evidence of the result, and the cost of the design.',why:x.idea},
 ] satisfies Question[],
 deeper:[{title:'Mechanism and invariant',body:x.idea+'\n\n'+x.steps.join(' → ')},{title:'Defend the design',body:x.trade+'\n\n'+x.example}],
 followups:[{q:x.fq,a:x.fa},{q:'Walk through a concrete example without skipping state transitions.',a:x.example},{q:'Which cost does this design move elsewhere?',a:x.trade}],
 tradeoff:{failure:x.problem,tradeoff:x.trade},model:x.idea,
 debug:{q:x.problem+' What would you inspect first?',a:x.steps.join(' → ')+' Compare before/after states under a reproducible workload; do not infer causality from one aggregate counter.'},rapid:[x.idea.split('. ')[0]+'.',x.fa.split('. ')[0]+'.'],
}));
export function enrichLesson(l:Lesson):Lesson {
 const followups=l.followups.length>=2?l.followups:[...l.followups,{q:'What cost does the design trade for its benefit?',a:l.tradeoff.tradeoff}];
 const trace=l.trace??[{label:'Identify the state',detail:l.idea},{label:'Apply the mechanism',detail:l.how.text},{label:'Check the outcome',detail:l.how.example??l.tradeoff.failure}];
 const checks=l.checks.map(q=>({...q,model:q.explain,why:q.explain,followups,tradeoff:l.tradeoff.tradeoff,...(q.kind==='numeric'?{assumptions:'Use the quantities and units stated in the prompt; ignore unmentioned overhead. See the solution for the path/counting convention.',sanity:'Check units and compare with the limiting case before accepting the result.'}:{})}));
 if(checks.length<3) checks.push({id:l.slug+'-derive',kind:'order',prompt:'Trace the mechanism in dependency order.',items:trace.map(s=>s.label),explain:trace.map(s=>s.detail).join('\n\n'),model:l.idea,why:l.how.text,followups,tradeoff:l.tradeoff.tradeoff});
 return {...l,trace,checks,followups,model:l.model??l.idea,debug:l.debug??{q:l.problem+' What would you debug first?',a:l.deeper.map(d=>d.body).join('\n\n')+'\n\n'+l.tradeoff.failure},rapid:l.rapid??[l.short,followups[0]?.a??l.idea]};
}